import 'package:flutter/material.dart'; import 'package:intl/intl.dart'; import '../repositories/app_repo.dart'; import '../services/export_service.dart';
class ReportsScreen extends StatefulWidget{const ReportsScreen({super.key});@override State<ReportsScreen> createState()=>_ReportsScreenState();}
class _ReportsScreenState extends State<ReportsScreen>{final repo=AppRepo();String period='Month';String customer='All';Future<List<Map<String,Object?>>> get data async {String? where;List<Object?> args=[];final now=DateTime.now();if(period=='Today'){where='date=?';args=[DateFormat('yyyy-MM-dd').format(now)];}else if(period=='Month'){where='date LIKE ?';args=['${DateFormat('yyyy-MM',).format(now)}%'];}else if(period=='Year'){where='date LIKE ?';args=['${DateFormat('yyyy',).format(now)}%'];}return repo.rows('work_entries',where:where,args:args,order:'date DESC');}
Future<void> export()async{final d=await data;final rows=<List<Object?>>[['Date','Payment Type','Rate','Minutes','Hours','Amount','Status'],...d.map((r)=>[r['date'],r['payment_type'],r['rate'],r['total_minutes'],r['total_hours'],r['amount'],r['status']])];final f=await ExportService().csvFile('work_report',rows);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('CSV exported: ${f.path}')));}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('गोस्वारा / Reports'),actions:[IconButton(onPressed:export,icon:const Icon(Icons.file_download))]),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(value:period,items:['Today','Month','Year','All'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>period=v!),decoration:const InputDecoration(labelText:'Report Period',border:OutlineInputBorder())),const SizedBox(height:16),FutureBuilder(future:data,builder:(c,s){if(!s.hasData)return const CircularProgressIndicator();final d=s.data!;double amt=0,h=0;for(final r in d){amt+=(r['amount']as num?)?.toDouble()??0;h+=(r['total_hours']as num?)?.toDouble()??0;}return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[_v('Entries',d.length.toString()),_v('Hours',h.toStringAsFixed(2)),_v('Earnings','₹${amt.toStringAsFixed(2)}')]))),const SizedBox(height:12),...d.map((r)=>ListTile(title:Text('${r['date']} • ${r['payment_type']}'),subtitle:Text('${r['total_minutes']} min • ${r['status']}'),trailing:Text('₹${((r['amount']as num?)??0).toStringAsFixed(2)}')))]);})]);}
Widget _v(String a,String b)=>Column(children:[Text(b,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text(a)]);}
